INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-01-01', 'lesson-paragraphs-b2-01', 1, 'paragraph', 'My name is Julia, and I am a nurse from the south of Brazil. I have worked in the same hospital for six years.', 'Meu nome é Julia e sou enfermeira do sul do Brasil. Trabalho no mesmo hospital há seis anos.', '/maɪ neɪm ɪz ˈdʒuːliə ænd aɪ æm ə nɜːrs frʌm ðə saʊθ ʌv brəˈzɪl aɪ hæv wɜːrkt ɪn ðə seɪm ˈhɑːspɪtəl fɔːr sɪks jɪrz/', 'Abertura: quem você é e há quanto tempo. Present perfect com "for" para duração.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Julia","pos":"proper noun","ipa":"/ˈdʒuːliə/","gloss":"Julia"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"nurse","pos":"noun","ipa":"/nɜːrs/","gloss":"enfermeiro"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"south","pos":"noun","ipa":"/saʊθ/","gloss":"sul"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"hospital","pos":"noun","ipa":"/ˈhɑːspɪtəl/","gloss":"hospital"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-02', 'lesson-paragraphs-b2-01', 2, 'paragraph', 'I chose this job because I like helping people. The hours are long, but I learn something new every day.', 'Escolhi esta profissão porque gosto de ajudar as pessoas. O horário é longo, mas aprendo algo novo todo dia.', '/aɪ tʃoʊz ðɪs dʒɑːb bɪˈkɔːz aɪ laɪk ˈhɛlpɪŋ ˈpiːpəl ðə aʊərz ɑːr lɔːŋ bʌt aɪ lɜːrn ˈsʌmθɪŋ nuː ˈɛvri deɪ/', 'Desenvolvimento: o motivo com "because" e um contraste com "but".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"chose","pos":"verb","ipa":"/tʃoʊz/","gloss":"escolheu"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"helping","pos":"verb","ipa":"/ˈhɛlpɪŋ/","gloss":"ajudando"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"learn","pos":"verb","ipa":"/lɜːrn/","gloss":"aprender"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-03', 'lesson-paragraphs-b2-01', 3, 'paragraph', 'Outside work, I enjoy cooking and walking by the sea. On weekends, I usually visit my parents.', 'Fora do trabalho, gosto de cozinhar e de caminhar à beira-mar. Nos fins de semana, costumo visitar meus pais.', '/ˌaʊtˈsaɪd wɜːrk aɪ ɪnˈdʒɔɪ ˈkʊkɪŋ ænd ˈwɔːkɪŋ baɪ ðə siː ɑːn ˈwiːkɛndz aɪ ˈjuːʒuəli ˈvɪzɪt maɪ ˈpɛrənts/', 'Detalhe pessoal: "enjoy" + -ing e advérbio de frequência antes do verbo.', '[]'::jsonb, '[{"surface":"Outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"cooking","pos":"verb","ipa":"/ˈkʊkɪŋ/","gloss":"cozinhar (atividade)"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"walking","pos":"noun","ipa":"/ˈwɔːkɪŋ/","gloss":"caminhada"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sea","pos":"noun","ipa":"/siː/","gloss":"mar"},{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"weekends","pos":"noun","ipa":"/ˈwiːkɛndz/","gloss":"fins de semana"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"visit","pos":"noun","ipa":"/ˈvɪzɪt/","gloss":"visita"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"parents","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"pais (pai e mãe)"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-01-04', 'lesson-paragraphs-b2-01', 4, 'paragraph', 'I am learning English because I want to work abroad one day. My goal is to feel confident in any conversation.', 'Estou aprendendo inglês porque quero trabalhar no exterior um dia. Meu objetivo é me sentir confiante em qualquer conversa.', '/aɪ æm ˈlɜːrnɪŋ ˈɪŋɡlɪʃ bɪˈkɔːz aɪ wɑːnt tuː wɜːrk əˈbrɔːd wʌn deɪ maɪ ɡoʊl ɪz tuː fiːl ˈkɑːnfɪdənt ɪn ˈɛni ˌkɑːnvərˈseɪʃən/', 'Fechamento: objetivo futuro. "Abroad" = no exterior, sem preposição.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"learning","pos":"verb","ipa":"/ˈlɜːrnɪŋ/","gloss":"aprendendo"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"abroad","pos":"adverb","ipa":"/əˈbrɔːd/","gloss":"no exterior"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"goal","pos":"noun","ipa":"/ɡoʊl/","gloss":"meta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"confident","pos":"adjective","ipa":"/ˈkɑːnfɪdənt/","gloss":"confiante"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"conversation","pos":"noun","ipa":"/ˌkɑːnvərˈseɪʃən/","gloss":"conversa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-02-01', 'lesson-paragraphs-b2-02', 1, 'paragraph', 'My day starts at six, when my alarm goes off. First, I make coffee and check the weather.', 'Meu dia começa às seis, quando o despertador toca. Primeiro, faço café e vejo a previsão do tempo.', '/maɪ deɪ stɑːrts æt sɪks wɛn maɪ əˈlɑːrm ɡoʊz ɔːf fɜːrst aɪ meɪk ˈkɔːfi ænd tʃɛk ðə ˈwɛðər/', '"Go off" = tocar (alarme). "First" abre a sequência.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"starts","pos":"verb","ipa":"/stɑːrts/","gloss":"começa"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"alarm","pos":"noun","ipa":"/əˈlɑːrm/","gloss":"despertador, alarme"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"First","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weather","pos":"noun","ipa":"/ˈwɛðər/","gloss":"tempo, clima"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-02', 'lesson-paragraphs-b2-02', 2, 'paragraph', 'Then I take the train to work, which takes about forty minutes. I usually read or listen to podcasts on the way.', 'Depois pego o trem para o trabalho, o que leva uns quarenta minutos. Costumo ler ou ouvir podcasts no caminho.', '/ðɛn aɪ teɪk ðə treɪn tuː wɜːrk wɪtʃ teɪks əˈbaʊt ˈfɔːrti ˈmɪnɪts aɪ ˈjuːʒuəli riːd ɔːr ˈlɪsən tuː ˈpɑːdkæsts ɑːn ðə weɪ/', '"Which" retoma a frase anterior. "Take" = pegar (transporte) e levar (tempo).', '[]'::jsonb, '[{"surface":"Then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"forty","pos":"numeral","ipa":"/ˈfɔːrti/","gloss":"quarenta"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"listen","pos":"verb","ipa":"/ˈlɪsən/","gloss":"escutar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"podcasts","pos":"noun","ipa":"/ˈpɑːdkæsts/","gloss":"podcasts"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-03', 'lesson-paragraphs-b2-02', 3, 'paragraph', 'In the afternoon, I have meetings until five. After that, I go to the gym if I still have energy.', 'À tarde, tenho reuniões até as cinco. Depois disso, vou à academia se ainda tiver energia.', '/ɪn ðə ˌæftərˈnuːn aɪ hæv ˈmiːtɪŋz ənˈtɪl faɪv ˈæftər ðæt aɪ ɡoʊ tuː ðə dʒɪm ɪf aɪ stɪl hæv ˈɛnərdʒi/', '"After that" continua a sequência. Condicional com presente.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"afternoon","pos":"noun","ipa":"/ˌæftərˈnuːn/","gloss":"tarde"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"meetings","pos":"noun","ipa":"/ˈmiːtɪŋz/","gloss":"reuniões"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"After","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"gym","pos":"noun","ipa":"/dʒɪm/","gloss":"academia"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"energy","pos":"noun","ipa":"/ˈɛnərdʒi/","gloss":"energia"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-02-04', 'lesson-paragraphs-b2-02', 4, 'paragraph', 'Finally, I cook dinner and relax for an hour. I try to go to bed before eleven, but it does not always happen.', 'Por fim, faço o jantar e relaxo por uma hora. Tento dormir antes das onze, mas nem sempre acontece.', '/ˈfaɪnəli aɪ kʊk ˈdɪnər ænd rɪˈlæks fɔːr ən ˈaʊər aɪ traɪ tuː ɡoʊ tuː bɛd bɪˈfɔːr ɪˈlɛvən bʌt ɪt dʌz nɑːt ˈɔːlweɪz ˈhæpən/', '"Finally" fecha a sequência. "Not always" = nem sempre.', '[]'::jsonb, '[{"surface":"Finally","pos":"adverb","ipa":"/ˈfaɪnəli/","gloss":"finalmente"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"cook","pos":"noun","ipa":"/kʊk/","gloss":"cozinheiro"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"relax","pos":"verb","ipa":"/rɪˈlæks/","gloss":"relaxar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"bed","pos":"noun","ipa":"/bɛd/","gloss":"cama"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"eleven","pos":"numeral","ipa":"/ɪˈlɛvən/","gloss":"onze"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"happen","pos":"verb","ipa":"/ˈhæpən/","gloss":"acontecer"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-03-01', 'lesson-paragraphs-b2-03', 1, 'paragraph', 'I live in a medium-sized city near the mountains. It is quiet during the week and busy on weekends.', 'Moro numa cidade de tamanho médio perto das montanhas. É tranquila durante a semana e movimentada nos fins de semana.', '/aɪ lɪv ɪn ə ˈmiːdiəm saɪzd ˈsɪti nɪr ðə ˈmaʊntənz ɪt ɪz ˈkwaɪət ˈdʊrɪŋ ðə wiːk ænd ˈbɪzi ɑːn ˈwiːkɛndz/', 'Abertura: onde fica e a impressão geral, com contraste de "quiet" e "busy".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"medium-sized","pos":"adjective","ipa":"/ˈmiːdiəm saɪzd/","gloss":"de tamanho médio"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"mountains","pos":"noun","ipa":"/ˈmaʊntənz/","gloss":"montanhas"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"weekends","pos":"noun","ipa":"/ˈwiːkɛndz/","gloss":"fins de semana"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-02', 'lesson-paragraphs-b2-03', 2, 'paragraph', 'The old town has narrow streets and colorful houses. There are small coffee shops on almost every corner.', 'O centro histórico tem ruas estreitas e casas coloridas. Há pequenos cafés em quase toda esquina.', '/ðə oʊld taʊn hæz ˈnæroʊ striːts ænd ˈkʌlərfəl ˈhaʊzɪz ðɛr ɑːr smɔːl ˈkɔːfi ʃɑːps ɑːn ˈɔːlmoʊst ˈɛvri ˈkɔːrnər/', 'Descrição com "there are". Adjetivos antes do substantivo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"narrow","pos":"adjective","ipa":"/ˈnæroʊ/","gloss":"estreito"},{"surface":"streets","pos":"noun","ipa":"/striːts/","gloss":"ruas"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"colorful","pos":"adjective","ipa":"/ˈkʌlərfəl/","gloss":"colorido"},{"surface":"houses","pos":"noun","ipa":"/ˈhaʊzɪz/","gloss":"casas"},{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"shops","pos":"noun","ipa":"/ʃɑːps/","gloss":"lojas"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"almost","pos":"adverb","ipa":"/ˈɔːlmoʊst/","gloss":"quase"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"corner","pos":"noun","ipa":"/ˈkɔːrnər/","gloss":"esquina"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-03', 'lesson-paragraphs-b2-03', 3, 'paragraph', 'However, public transport is not very good. Most people need a car to get around.', 'No entanto, o transporte público não é muito bom. A maioria das pessoas precisa de carro para se locomover.', '/haʊˈɛvər ˈpʌblɪk ˈtrænspɔːrt ɪz nɑːt ˈvɛri ɡʊd moʊst ˈpiːpəl niːd ə kɑːr tuː ɡɛt əˈraʊnd/', '"However" introduz o lado negativo. "Get around" = locomover-se.', '[]'::jsonb, '[{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"public","pos":"adjective","ipa":"/ˈpʌblɪk/","gloss":"público"},{"surface":"transport","pos":"noun","ipa":"/ˈtrænspɔːrt/","gloss":"transporte"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"Most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"around","pos":"adverb","ipa":"/əˈraʊnd/","gloss":"ao redor, por"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-03-04', 'lesson-paragraphs-b2-03', 4, 'paragraph', 'Overall, it is a pleasant place to live. I would recommend a visit in the spring, when the parks are full of flowers.', 'No geral, é um lugar agradável para morar. Eu recomendaria uma visita na primavera, quando os parques estão cheios de flores.', '/ˌoʊvərˈɔːl ɪt ɪz ə ˈplɛzənt pleɪs tuː lɪv aɪ wʊd ˌrɛkəˈmɛnd ə ˈvɪzɪt ɪn ðə sprɪŋ wɛn ðə pɑːrks ɑːr fʊl ʌv ˈflaʊərz/', '"Overall" = no geral, conclusão. "Would recommend" = recomendação educada.', '[]'::jsonb, '[{"surface":"Overall","pos":"adverb","ipa":"/ˌoʊvərˈɔːl/","gloss":"no geral"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pleasant","pos":"adjective","ipa":"/ˈplɛzənt/","gloss":"agradável"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"recommend","pos":"verb","ipa":"/ˌrɛkəˈmɛnd/","gloss":"recomendar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"visit","pos":"noun","ipa":"/ˈvɪzɪt/","gloss":"visita"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"spring","pos":"noun","ipa":"/sprɪŋ/","gloss":"primavera"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"parks","pos":"noun","ipa":"/pɑːrks/","gloss":"parques"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"full","pos":"adjective","ipa":"/fʊl/","gloss":"cheio"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"flowers","pos":"noun","ipa":"/ˈflaʊərz/","gloss":"flores"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-04-01', 'lesson-paragraphs-b2-04', 1, 'paragraph', 'Last summer, my friends and I traveled to the coast of Portugal. We rented a small car and drove from town to town.', 'No verão passado, eu e meus amigos viajamos para o litoral de Portugal. Alugamos um carro pequeno e fomos de cidade em cidade.', '/læst ˈsʌmər maɪ frɛndz ænd aɪ ˈtrævəld tuː ðə koʊst ʌv ˈpɔːrtʃəɡəl wiː ˈrɛntɪd ə smɔːl kɑːr ænd droʊv frʌm taʊn tuː taʊn/', 'Abertura com marcador de tempo. Passado simples para a sequência.', '[]'::jsonb, '[{"surface":"Last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"summer","pos":"noun","ipa":"/ˈsʌmər/","gloss":"verão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"traveled","pos":"verb","ipa":"/ˈtrævəld/","gloss":"viajou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"coast","pos":"noun","ipa":"/koʊst/","gloss":"litoral"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"Portugal","pos":"proper noun","ipa":"/ˈpɔːrtʃəɡəl/","gloss":"Portugal"},{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"rented","pos":"verb","ipa":"/ˈrɛntɪd/","gloss":"alugou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"drove","pos":"verb","ipa":"/droʊv/","gloss":"dirigiu"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"town","pos":"noun","ipa":"/taʊn/","gloss":"cidade pequena"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-02', 'lesson-paragraphs-b2-04', 2, 'paragraph', 'On the second day, the car broke down in the middle of nowhere. We had no signal, so we walked to the nearest village.', 'No segundo dia, o carro quebrou no meio do nada. Estávamos sem sinal, então andamos até o vilarejo mais próximo.', '/ɑːn ðə ˈsɛkənd deɪ ðə kɑːr broʊk daʊn ɪn ðə ˈmɪdəl ʌv ˈnoʊwɛr wiː hæd noʊ ˈsɪɡnəl soʊ wiː wɔːkt tuː ðə ˈnɪrɪst ˈvɪlɪdʒ/', '"Break down" = quebrar (veículo). "In the middle of nowhere" = no meio do nada.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"middle","pos":"adjective","ipa":"/ˈmɪdəl/","gloss":"do meio"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"nowhere","pos":"adverb","ipa":"/ˈnoʊwɛr/","gloss":"lugar nenhum"},{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"no","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"signal","pos":"noun","ipa":"/ˈsɪɡnəl/","gloss":"sinal"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"walked","pos":"verb","ipa":"/wɔːkt/","gloss":"caminhou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"nearest","pos":"adjective","ipa":"/ˈnɪrɪst/","gloss":"mais próximo"},{"surface":"village","pos":"noun","ipa":"/ˈvɪlɪdʒ/","gloss":"vilarejo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-03', 'lesson-paragraphs-b2-04', 3, 'paragraph', 'A farmer helped us and even invited us for lunch. We ate fresh bread and grilled fish while we waited for the mechanic.', 'Um fazendeiro nos ajudou e até nos convidou para almoçar. Comemos pão fresco e peixe grelhado enquanto esperávamos o mecânico.', '/ə ˈfɑːrmər hɛlpt ʌs ænd ˈiːvən ɪnˈvaɪtɪd ʌs fɔːr lʌntʃ wiː eɪt frɛʃ brɛd ænd ɡrɪld fɪʃ waɪl wiː ˈweɪtɪd fɔːr ðə məˈkænɪk/', '"Even" = até (surpresa). "While" liga duas ações simultâneas.', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"farmer","pos":"noun","ipa":"/ˈfɑːrmər/","gloss":"fazendeiro"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"even","pos":"adverb","ipa":"/ˈiːvən/","gloss":"até, mesmo"},{"surface":"invited","pos":"verb","ipa":"/ɪnˈvaɪtɪd/","gloss":"convidado"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"},{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"ate","pos":"verb","ipa":"/eɪt/","gloss":"comeu"},{"surface":"fresh","pos":"adjective","ipa":"/frɛʃ/","gloss":"fresco"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"grilled","pos":"adjective","ipa":"/ɡrɪld/","gloss":"grelhado"},{"surface":"fish","pos":"noun","ipa":"/fɪʃ/","gloss":"peixe"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"waited","pos":"verb","ipa":"/ˈweɪtɪd/","gloss":"esperou"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"mechanic","pos":"noun","ipa":"/məˈkænɪk/","gloss":"mecânico"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-04-04', 'lesson-paragraphs-b2-04', 4, 'paragraph', 'Looking back, that problem became the best part of the trip. Sometimes the plans that fail are the ones we remember.', 'Olhando para trás, aquele problema virou a melhor parte da viagem. Às vezes, os planos que dão errado são os que lembramos.', '/ˈlʊkɪŋ bæk ðæt ˈprɑːbləm bɪˈkeɪm ðə bɛst pɑːrt ʌv ðə trɪp ˈsʌmtaɪmz ðə plænz ðæt feɪl ɑːr ðə wʌnz wiː rɪˈmɛmbər/', '"Looking back" = em retrospecto. Fechamento com reflexão.', '[]'::jsonb, '[{"surface":"Looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"became","pos":"verb","ipa":"/bɪˈkeɪm/","gloss":"tornou-se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"part","pos":"noun","ipa":"/pɑːrt/","gloss":"parte"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"},{"surface":"Sometimes","pos":"adverb","ipa":"/ˈsʌmtaɪmz/","gloss":"às vezes"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plans","pos":"noun","ipa":"/plænz/","gloss":"planos"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"fail","pos":"verb","ipa":"/feɪl/","gloss":"reprovar, falhar"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"ones","pos":"pronoun","ipa":"/wʌnz/","gloss":"os, aqueles"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-05-01', 'lesson-paragraphs-b2-05', 1, 'paragraph', 'Many companies now allow people to work from home. In my opinion, this is a positive change for most workers.', 'Muitas empresas agora permitem que as pessoas trabalhem de casa. Na minha opinião, é uma mudança positiva para a maioria dos trabalhadores.', '/ˈmɛni ˈkʌmpəniz naʊ əˈlaʊ ˈpiːpəl tuː wɜːrk frʌm hoʊm ɪn maɪ əˈpɪnjən ðɪs ɪz ə ˈpɑːzətɪv tʃeɪndʒ fɔːr moʊst ˈwɜːrkərz/', 'Abertura: contexto e tese. "Allow someone to" + verbo.', '[]'::jsonb, '[{"surface":"Many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"companies","pos":"noun","ipa":"/ˈkʌmpəniz/","gloss":"empresas"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"allow","pos":"verb","ipa":"/əˈlaʊ/","gloss":"permitir"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"opinion","pos":"noun","ipa":"/əˈpɪnjən/","gloss":"opinião"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"positive","pos":"adjective","ipa":"/ˈpɑːzətɪv/","gloss":"positivo"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"workers","pos":"noun","ipa":"/ˈwɜːrkərz/","gloss":"trabalhadores"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-02', 'lesson-paragraphs-b2-05', 2, 'paragraph', 'First of all, people save time and money on transport. They can use those hours to rest or to be with their families.', 'Em primeiro lugar, as pessoas economizam tempo e dinheiro com transporte. Podem usar essas horas para descansar ou ficar com a família.', '/fɜːrst ʌv ɔːl ˈpiːpəl seɪv taɪm ænd ˈmʌni ɑːn ˈtrænspɔːrt ðeɪ kæn juːz ðoʊz aʊərz tuː rɛst ɔːr tuː biː wɪð ðɛr ˈfæməliz/', '"First of all" apresenta o primeiro argumento.', '[]'::jsonb, '[{"surface":"First","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"save","pos":"verb","ipa":"/seɪv/","gloss":"economizar, salvar"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"transport","pos":"noun","ipa":"/ˈtrænspɔːrt/","gloss":"transporte"},{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"those","pos":"determiner","ipa":"/ðoʊz/","gloss":"aqueles, essas"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rest","pos":"verb","ipa":"/rɛst/","gloss":"descansar"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"families","pos":"noun","ipa":"/ˈfæməliz/","gloss":"famílias"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-03', 'lesson-paragraphs-b2-05', 3, 'paragraph', 'On the other hand, some people feel lonely at home. It can also be harder to separate work from personal life.', 'Por outro lado, algumas pessoas se sentem sozinhas em casa. Também pode ser mais difícil separar trabalho e vida pessoal.', '/ɑːn ðə ˈʌðər hænd sʌm ˈpiːpəl fiːl ˈloʊnli æt hoʊm ɪt kæn ˈɔːlsoʊ biː ˈhɑːrdər tuː ˈsɛpərət wɜːrk frʌm ˈpɜːrsənəl laɪf/', '"On the other hand" apresenta o contra-argumento.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"other","pos":"pronoun","ipa":"/ˈʌðər/","gloss":"outro"},{"surface":"hand","pos":"noun","ipa":"/hænd/","gloss":"mão, ajuda"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"lonely","pos":"adjective","ipa":"/ˈloʊnli/","gloss":"sozinho, solitário"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"harder","pos":"adjective","ipa":"/ˈhɑːrdər/","gloss":"mais difícil"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"separate","pos":"adjective","ipa":"/ˈsɛpərət/","gloss":"separado"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"personal","pos":"adjective","ipa":"/ˈpɜːrsənəl/","gloss":"pessoal"},{"surface":"life","pos":"noun","ipa":"/laɪf/","gloss":"vida"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-05-04', 'lesson-paragraphs-b2-05', 4, 'paragraph', 'In conclusion, I believe the best option is a mix of both. Companies should let employees choose what works for them.', 'Em conclusão, acredito que a melhor opção é uma mistura dos dois. As empresas deveriam deixar os funcionários escolherem o que funciona para eles.', '/ɪn kənˈkluːʒən aɪ bɪˈliːv ðə bɛst ˈɑːpʃən ɪz ə mɪks ʌv boʊθ ˈkʌmpəniz ʃʊd lɛt ɪmˈplɔɪiːz tʃuːz wʌt wɜːrks fɔːr ðɛm/', '"In conclusion" fecha. "Let someone" + verbo sem "to".', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"conclusion","pos":"noun","ipa":"/kənˈkluːʒən/","gloss":"conclusão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"believe","pos":"verb","ipa":"/bɪˈliːv/","gloss":"acreditar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"mix","pos":"verb","ipa":"/mɪks/","gloss":"misturar"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"both","pos":"determiner","ipa":"/boʊθ/","gloss":"ambos"},{"surface":"Companies","pos":"noun","ipa":"/ˈkʌmpəniz/","gloss":"empresas"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"employees","pos":"noun","ipa":"/ɪmˈplɔɪiːz/","gloss":"funcionários"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-06-01', 'lesson-paragraphs-b2-06', 1, 'paragraph', 'Dear Sir or Madam, I am writing to complain about an order I placed on your website last month.', 'Prezados, escrevo para reclamar de um pedido que fiz no site de vocês no mês passado.', '/dɪr sɜːr ɔːr ˈmædəm aɪ æm ˈraɪtɪŋ tuː kəmˈpleɪn əˈbaʊt ən ˈɔːrdər aɪ pleɪst ɑːn jʊr ˈwɛbsaɪt læst mʌnθ/', '"Dear Sir or Madam" quando não se sabe o nome. "I am writing to" abre e-mails formais.', '[]'::jsonb, '[{"surface":"Dear","pos":"adjective","ipa":"/dɪr/","gloss":"prezado, querido"},{"surface":"Sir","pos":"noun","ipa":"/sɜːr/","gloss":"senhor"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"Madam","pos":"noun","ipa":"/ˈmædəm/","gloss":"senhora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"writing","pos":"noun","ipa":"/ˈraɪtɪŋ/","gloss":"escrita"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"complain","pos":"verb","ipa":"/kəmˈpleɪn/","gloss":"reclamar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"order","pos":"verb","ipa":"/ˈɔːrdər/","gloss":"pedir (comida)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"placed","pos":"verb","ipa":"/pleɪst/","gloss":"fez (pedido), colocou"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"website","pos":"noun","ipa":"/ˈwɛbsaɪt/","gloss":"site"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-02', 'lesson-paragraphs-b2-06', 2, 'paragraph', 'The package arrived two weeks late, and one of the items was damaged. I have attached photos of the box and the product.', 'O pacote chegou com duas semanas de atraso, e um dos itens estava danificado. Anexei fotos da caixa e do produto.', '/ðə ˈpækɪdʒ əˈraɪvd tuː wiːks leɪt ænd wʌn ʌv ðə ˈaɪtəmz wɑːz ˈdæmɪdʒd aɪ hæv əˈtætʃt ˈfoʊtoʊz ʌv ðə bɑːks ænd ðə ˈprɑːdʌkt/', 'Fatos objetivos, sem emoção. "Attach" = anexar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"weeks","pos":"noun","ipa":"/wiːks/","gloss":"semanas"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"items","pos":"noun","ipa":"/ˈaɪtəmz/","gloss":"itens"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"damaged","pos":"adjective","ipa":"/ˈdæmɪdʒd/","gloss":"danificado"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"attached","pos":"adjective","ipa":"/əˈtætʃt/","gloss":"anexado"},{"surface":"photos","pos":"noun","ipa":"/ˈfoʊtoʊz/","gloss":"fotos"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"box","pos":"noun","ipa":"/bɑːks/","gloss":"caixa"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"product","pos":"noun","ipa":"/ˈprɑːdʌkt/","gloss":"produto"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-03', 'lesson-paragraphs-b2-06', 3, 'paragraph', 'I would appreciate it if you could send a replacement or refund the full amount.', 'Eu agradeceria se vocês pudessem enviar um substituto ou reembolsar o valor total.', '/aɪ wʊd əˈpriːʃieɪt ɪt ɪf juː kʊd sɛnd ə rɪˈpleɪsmənt ɔːr ˈriːfʌnd ðə fʊl əˈmaʊnt/', '"I would appreciate it if you could" = pedido formal e educado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"appreciate","pos":"verb","ipa":"/əˈpriːʃieɪt/","gloss":"agradecer, valorizar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"replacement","pos":"noun","ipa":"/rɪˈpleɪsmənt/","gloss":"substituto"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"refund","pos":"noun","ipa":"/ˈriːfʌnd/","gloss":"reembolso"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"full","pos":"adjective","ipa":"/fʊl/","gloss":"cheio"},{"surface":"amount","pos":"noun","ipa":"/əˈmaʊnt/","gloss":"valor, quantia"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-06-04', 'lesson-paragraphs-b2-06', 4, 'paragraph', 'I look forward to hearing from you soon. Kind regards, Daniel Costa.', 'Aguardo seu retorno em breve. Atenciosamente, Daniel Costa.', '/aɪ lʊk ˈfɔːrwərd tuː ˈhɪrɪŋ frʌm juː suːn kaɪnd rɪˈɡɑːrdz ˈdænjəl ˈkɑːstə/', '"I look forward to" + -ing. "Kind regards" = atenciosamente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"forward","pos":"adverb","ipa":"/ˈfɔːrwərd/","gloss":"adiante (look forward)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"hearing","pos":"verb","ipa":"/ˈhɪrɪŋ/","gloss":"ouvir, ter notícias"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"},{"surface":"Kind","pos":"adjective","ipa":"/kaɪnd/","gloss":"gentil"},{"surface":"regards","pos":"noun","ipa":"/rɪˈɡɑːrdz/","gloss":"cumprimentos"},{"surface":"Daniel","pos":"proper noun","ipa":"/ˈdænjəl/","gloss":"Daniel"},{"surface":"Costa","pos":"proper noun","ipa":"/ˈkɑːstə/","gloss":"Costa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-07-01', 'lesson-paragraphs-b2-07', 1, 'paragraph', 'Last night I watched a film about a family that runs a small bakery. It is simple, but it stayed with me for hours.', 'Ontem à noite assisti a um filme sobre uma família que tem uma padaria pequena. É simples, mas ficou comigo por horas.', '/læst naɪt aɪ wɑːtʃt ə fɪlm əˈbaʊt ə ˈfæməli ðæt rʌnz ə smɔːl ˈbeɪkəri ɪt ɪz ˈsɪmpəl bʌt ɪt steɪd wɪð miː fɔːr aʊərz/', 'Abertura: o que é e a impressão geral. "Stay with me" = não sair da cabeça.', '[]'::jsonb, '[{"surface":"Last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"watched","pos":"verb","ipa":"/wɑːtʃt/","gloss":"assistiu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"runs","pos":"verb","ipa":"/rʌnz/","gloss":"administra; corre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"bakery","pos":"noun","ipa":"/ˈbeɪkəri/","gloss":"padaria"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"simple","pos":"adjective","ipa":"/ˈsɪmpəl/","gloss":"simples"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"hours","pos":"noun","ipa":"/aʊərz/","gloss":"horas"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-02', 'lesson-paragraphs-b2-07', 2, 'paragraph', 'The acting is natural, especially from the two children. The dialogue feels real, as if you were listening to your neighbors.', 'As atuações são naturais, especialmente das duas crianças. Os diálogos parecem reais, como se você estivesse ouvindo seus vizinhos.', '/ðə ˈæktɪŋ ɪz ˈnætʃərəl ɪˈspɛʃəli frʌm ðə tuː ˈtʃɪldrən ðə ˈdaɪəlɔːɡ fiːlz ˈriːəl æz ɪf juː wɜːr ˈlɪsənɪŋ tuː jʊr ˈneɪbərz/', 'Ponto positivo. "As if" + passado = como se.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"acting","pos":"noun","ipa":"/ˈæktɪŋ/","gloss":"atuação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"natural","pos":"adjective","ipa":"/ˈnætʃərəl/","gloss":"natural"},{"surface":"especially","pos":"adverb","ipa":"/ɪˈspɛʃəli/","gloss":"especialmente"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dialogue","pos":"noun","ipa":"/ˈdaɪəlɔːɡ/","gloss":"diálogo"},{"surface":"feels","pos":"verb","ipa":"/fiːlz/","gloss":"parece, sente"},{"surface":"real","pos":"adjective","ipa":"/ˈriːəl/","gloss":"real"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"listening","pos":"verb","ipa":"/ˈlɪsənɪŋ/","gloss":"ouvindo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"neighbors","pos":"noun","ipa":"/ˈneɪbərz/","gloss":"vizinhos"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-03', 'lesson-paragraphs-b2-07', 3, 'paragraph', 'My only criticism is that the middle part is a little slow. Some scenes could have been shorter.', 'Minha única crítica é que a parte do meio é um pouco lenta. Algumas cenas poderiam ter sido mais curtas.', '/maɪ ˈoʊnli ˈkrɪtɪsɪzəm ɪz ðæt ðə ˈmɪdəl pɑːrt ɪz ə ˈlɪtəl sloʊ sʌm siːnz kʊd hæv bɪn ˈʃɔːrtər/', 'Ponto negativo suave. "Could have been" = poderia ter sido.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"criticism","pos":"noun","ipa":"/ˈkrɪtɪsɪzəm/","gloss":"crítica"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"middle","pos":"adjective","ipa":"/ˈmɪdəl/","gloss":"do meio"},{"surface":"part","pos":"noun","ipa":"/pɑːrt/","gloss":"parte"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"slow","pos":"adjective","ipa":"/sloʊ/","gloss":"lento"},{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"scenes","pos":"noun","ipa":"/siːnz/","gloss":"cenas"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"shorter","pos":"adjective","ipa":"/ˈʃɔːrtər/","gloss":"mais curto"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-07-04', 'lesson-paragraphs-b2-07', 4, 'paragraph', 'Overall, I would give it four stars out of five. It is perfect for a quiet evening at home.', 'No geral, eu daria quatro estrelas de cinco. É perfeito para uma noite tranquila em casa.', '/ˌoʊvərˈɔːl aɪ wʊd ɡɪv ɪt fɔːr stɑːrz aʊt ʌv faɪv ɪt ɪz ˈpɜːrfɪkt fɔːr ə ˈkwaɪət ˈiːvnɪŋ æt hoʊm/', 'Nota final com "out of" = de (num total).', '[]'::jsonb, '[{"surface":"Overall","pos":"adverb","ipa":"/ˌoʊvərˈɔːl/","gloss":"no geral"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"four","pos":"numeral","ipa":"/fɔːr/","gloss":"quatro"},{"surface":"stars","pos":"noun","ipa":"/stɑːrz/","gloss":"estrelas"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"perfect","pos":"adjective","ipa":"/ˈpɜːrfɪkt/","gloss":"perfeito"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-08-01', 'lesson-paragraphs-b2-08', 1, 'paragraph', 'Making good bread at home is easier than most people think. You only need flour, water, salt and yeast.', 'Fazer um bom pão em casa é mais fácil do que a maioria pensa. Você só precisa de farinha, água, sal e fermento.', '/ˈmeɪkɪŋ ɡʊd brɛd æt hoʊm ɪz ˈiːziər ðæn moʊst ˈpiːpəl θɪŋk juː ˈoʊnli niːd ˈflaʊər ˈwɔːtər sɔːlt ænd jiːst/', 'Abertura com comparativo "easier than". Lista de ingredientes.', '[]'::jsonb, '[{"surface":"Making","pos":"verb","ipa":"/ˈmeɪkɪŋ/","gloss":"fazendo"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"easier","pos":"adjective","ipa":"/ˈiːziər/","gloss":"mais fácil"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"flour","pos":"noun","ipa":"/ˈflaʊər/","gloss":"farinha"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"salt","pos":"noun","ipa":"/sɔːlt/","gloss":"sal"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"yeast","pos":"noun","ipa":"/jiːst/","gloss":"fermento"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-02', 'lesson-paragraphs-b2-08', 2, 'paragraph', 'First, mix the ingredients in a large bowl until the dough comes together. Then cover it and let it rest for an hour.', 'Primeiro, misture os ingredientes numa tigela grande até a massa ficar homogênea. Depois cubra e deixe descansar por uma hora.', '/fɜːrst mɪks ðə ɪnˈɡriːdiənts ɪn ə lɑːrdʒ boʊl ənˈtɪl ðə doʊ kʌmz təˈɡɛðər ðɛn ˈkʌvər ɪt ænd lɛt ɪt rɛst fɔːr ən ˈaʊər/', 'Imperativo para instruções. "Let it rest" = deixe descansar.', '[]'::jsonb, '[{"surface":"First","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"mix","pos":"verb","ipa":"/mɪks/","gloss":"misturar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"ingredients","pos":"noun","ipa":"/ɪnˈɡriːdiənts/","gloss":"ingredientes"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"large","pos":"adjective","ipa":"/lɑːrdʒ/","gloss":"grande"},{"surface":"bowl","pos":"noun","ipa":"/boʊl/","gloss":"tigela"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dough","pos":"noun","ipa":"/doʊ/","gloss":"massa"},{"surface":"comes","pos":"verb","ipa":"/kʌmz/","gloss":"vem (he/she/it)"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"},{"surface":"Then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"cover","pos":"noun","ipa":"/ˈkʌvər/","gloss":"entrada (cover charge)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rest","pos":"verb","ipa":"/rɛst/","gloss":"descansar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-03', 'lesson-paragraphs-b2-08', 3, 'paragraph', 'Once the dough has doubled in size, shape it into a ball. Bake it in a hot oven for about forty minutes.', 'Assim que a massa dobrar de tamanho, modele em forma de bola. Asse em forno quente por uns quarenta minutos.', '/wʌns ðə doʊ hæz ˈdʌbəld ɪn saɪz ʃeɪp ɪt ˈɪntuː ə bɔːl beɪk ɪt ɪn ə hɑːt ˈʌvən fɔːr əˈbaʊt ˈfɔːrti ˈmɪnɪts/', '"Once" = assim que. Present perfect depois de "once" para ação concluída.', '[]'::jsonb, '[{"surface":"Once","pos":"adverb","ipa":"/wʌns/","gloss":"uma vez"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dough","pos":"noun","ipa":"/doʊ/","gloss":"massa"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"doubled","pos":"verb","ipa":"/ˈdʌbəld/","gloss":"dobrou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"size","pos":"noun","ipa":"/saɪz/","gloss":"tamanho"},{"surface":"shape","pos":"noun","ipa":"/ʃeɪp/","gloss":"forma"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"ball","pos":"noun","ipa":"/bɔːl/","gloss":"bola"},{"surface":"Bake","pos":"verb","ipa":"/beɪk/","gloss":"assar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hot","pos":"adjective","ipa":"/hɑːt/","gloss":"quente"},{"surface":"oven","pos":"noun","ipa":"/ˈʌvən/","gloss":"forno"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"forty","pos":"numeral","ipa":"/ˈfɔːrti/","gloss":"quarenta"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-08-04', 'lesson-paragraphs-b2-08', 4, 'paragraph', 'The bread is ready when it sounds hollow if you tap the bottom. Let it cool before you cut it.', 'O pão está pronto quando soa oco ao bater no fundo. Deixe esfriar antes de cortar.', '/ðə brɛd ɪz ˈrɛdi wɛn ɪt saʊndz ˈhɑːloʊ ɪf juː tæp ðə ˈbɑːtəm lɛt ɪt kuːl bɪˈfɔːr juː kʌt ɪt/', 'Fechamento: como saber que terminou. "Before you" + presente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"sounds","pos":"verb","ipa":"/saʊndz/","gloss":"soa, parece"},{"surface":"hollow","pos":"adjective","ipa":"/ˈhɑːloʊ/","gloss":"oco"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tap","pos":"noun","ipa":"/tæp/","gloss":"torneira; chope"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bottom","pos":"noun","ipa":"/ˈbɑːtəm/","gloss":"fundo"},{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"cool","pos":"adjective","ipa":"/kuːl/","gloss":"legal, massa"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"cut","pos":"verb","ipa":"/kʌt/","gloss":"cortar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-09-01', 'lesson-paragraphs-b2-09', 1, 'paragraph', 'When people move to a new city, they often have to choose between renting and buying a home.', 'Quando as pessoas se mudam para uma cidade nova, muitas vezes têm que escolher entre alugar e comprar uma casa.', '/wɛn ˈpiːpəl muːv tuː ə nuː ˈsɪti ðeɪ ˈɔːfən hæv tuː tʃuːz bɪˈtwiːn ˈrɛntɪŋ ænd ˈbaɪɪŋ ə hoʊm/', 'Abertura: apresenta as duas opções com "between… and".', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"often","pos":"adverb","ipa":"/ˈɔːfən/","gloss":"frequentemente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"choose","pos":"verb","ipa":"/tʃuːz/","gloss":"escolher"},{"surface":"between","pos":"preposition","ipa":"/bɪˈtwiːn/","gloss":"entre"},{"surface":"renting","pos":"verb","ipa":"/ˈrɛntɪŋ/","gloss":"alugando, alugar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"buying","pos":"verb","ipa":"/ˈbaɪɪŋ/","gloss":"comprando, comprar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-02', 'lesson-paragraphs-b2-09', 2, 'paragraph', 'Renting is more flexible. If you get a job somewhere else, you can leave without selling anything.', 'Alugar é mais flexível. Se você arranja emprego em outro lugar, pode ir embora sem vender nada.', '/ˈrɛntɪŋ ɪz mɔːr ˈflɛksəbəl ɪf juː ɡɛt ə dʒɑːb ˈsʌmwɛr ɛls juː kæn liːv wɪˈðaʊt ˈsɛlɪŋ ˈɛniθɪŋ/', 'Vantagem da primeira opção. Comparativo com "more".', '[]'::jsonb, '[{"surface":"Renting","pos":"verb","ipa":"/ˈrɛntɪŋ/","gloss":"alugando, alugar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"flexible","pos":"adjective","ipa":"/ˈflɛksəbəl/","gloss":"flexível"},{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"somewhere","pos":"adverb","ipa":"/ˈsʌmwɛr/","gloss":"em algum lugar"},{"surface":"else","pos":"adverb","ipa":"/ɛls/","gloss":"mais, outro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"without","pos":"preposition","ipa":"/wɪˈðaʊt/","gloss":"sem"},{"surface":"selling","pos":"verb","ipa":"/ˈsɛlɪŋ/","gloss":"vendendo"},{"surface":"anything","pos":"pronoun","ipa":"/ˈɛniθɪŋ/","gloss":"algo, alguma coisa"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-03', 'lesson-paragraphs-b2-09', 3, 'paragraph', 'Buying, by contrast, gives you stability. Although the monthly cost may be higher at first, you are paying for something that is yours.', 'Comprar, por outro lado, dá estabilidade. Embora o custo mensal possa ser mais alto no início, você está pagando por algo que é seu.', '/ˈbaɪɪŋ baɪ ˈkɑːntræst ɡɪvz juː stəˈbɪləti ɔːlˈðoʊ ðə ˈmʌnθli kɔːst meɪ biː ˈhaɪər æt fɜːrst juː ɑːr ˈpeɪɪŋ fɔːr ˈsʌmθɪŋ ðæt ɪz jʊrz/', '"By contrast" = em contraste. "Although" introduz a concessão.', '[]'::jsonb, '[{"surface":"Buying","pos":"verb","ipa":"/ˈbaɪɪŋ/","gloss":"comprando, comprar"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"contrast","pos":"noun","ipa":"/ˈkɑːntræst/","gloss":"contraste"},{"surface":"gives","pos":"verb","ipa":"/ɡɪvz/","gloss":"dá"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"stability","pos":"noun","ipa":"/stəˈbɪləti/","gloss":"estabilidade"},{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"monthly","pos":"adjective","ipa":"/ˈmʌnθli/","gloss":"mensal"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"higher","pos":"adjective","ipa":"/ˈhaɪər/","gloss":"mais alto, maior"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"paying","pos":"verb","ipa":"/ˈpeɪɪŋ/","gloss":"pagando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"yours","pos":"pronoun","ipa":"/jʊrz/","gloss":"seu, o seu"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-09-04', 'lesson-paragraphs-b2-09', 4, 'paragraph', 'In the end, the right choice depends on your plans. If you are not sure where you will be in five years, renting is probably safer.', 'No fim, a escolha certa depende dos seus planos. Se você não sabe onde estará daqui a cinco anos, alugar provavelmente é mais seguro.', '/ɪn ðə ɛnd ðə raɪt tʃɔɪs dɪˈpɛndz ɑːn jʊr plænz ɪf juː ɑːr nɑːt ʃʊr wɛr juː wɪl biː ɪn faɪv jɪrz ˈrɛntɪŋ ɪz ˈprɑːbəbli ˈseɪfər/', '"Depends on" + substantivo. Conclusão com recomendação condicional.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"choice","pos":"noun","ipa":"/tʃɔɪs/","gloss":"escolha"},{"surface":"depends","pos":"verb","ipa":"/dɪˈpɛndz/","gloss":"depende"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"plans","pos":"noun","ipa":"/plænz/","gloss":"planos"},{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"renting","pos":"verb","ipa":"/ˈrɛntɪŋ/","gloss":"alugando, alugar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"probably","pos":"adverb","ipa":"/ˈprɑːbəbli/","gloss":"provavelmente"},{"surface":"safer","pos":"adjective","ipa":"/ˈseɪfər/","gloss":"mais seguro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-paragraphs-b2-10-01', 'lesson-paragraphs-b2-10', 1, 'paragraph', 'Next year is going to be a big year for me. I am planning to change jobs and move to a new city.', 'O ano que vem vai ser um ano importante para mim. Estou planejando mudar de emprego e de cidade.', '/nɛkst jɪr ɪz ˈɡoʊɪŋ tuː biː ə bɪɡ jɪr fɔːr miː aɪ æm ˈplænɪŋ tuː tʃeɪndʒ dʒɑːbz ænd muːv tuː ə nuː ˈsɪti/', '"Going to" para planos já decididos.', '[]'::jsonb, '[{"surface":"Next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"planning","pos":"verb","ipa":"/ˈplænɪŋ/","gloss":"planejando"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"jobs","pos":"noun","ipa":"/dʒɑːbz/","gloss":"empregos"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-02', 'lesson-paragraphs-b2-10', 2, 'paragraph', 'I have already started saving money and looking for apartments. By December, I hope to have a few interviews scheduled.', 'Já comecei a economizar e procurar apartamentos. Até dezembro, espero ter algumas entrevistas marcadas.', '/aɪ hæv ɔːlˈrɛdi ˈstɑːrtɪd ˈseɪvɪŋ ˈmʌni ænd ˈlʊkɪŋ fɔːr əˈpɑːrtmənts baɪ dɪˈsɛmbər aɪ hoʊp tuː hæv ə fjuː ˈɪntərvjuːz ˈskɛdʒuːld/', '"Already" com present perfect. "By" + data = até.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"saving","pos":"verb","ipa":"/ˈseɪvɪŋ/","gloss":"economizando"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"apartments","pos":"noun","ipa":"/əˈpɑːrtmənts/","gloss":"apartamentos"},{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"December","pos":"proper noun","ipa":"/dɪˈsɛmbər/","gloss":"dezembro"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hope","pos":"verb","ipa":"/hoʊp/","gloss":"esperar (ter esperança)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"interviews","pos":"noun","ipa":"/ˈɪntərvjuːz/","gloss":"entrevistas"},{"surface":"scheduled","pos":"adjective","ipa":"/ˈskɛdʒuːld/","gloss":"marcado, agendado"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-03', 'lesson-paragraphs-b2-10', 3, 'paragraph', 'Of course, I am a little nervous. Leaving my friends will not be easy, and everything will be new.', 'Claro, estou um pouco nervoso. Deixar meus amigos não vai ser fácil, e tudo vai ser novo.', '/ʌv kɔːrs aɪ æm ə ˈlɪtəl ˈnɜːrvəs ˈliːvɪŋ maɪ frɛndz wɪl nɑːt biː ˈiːzi ænd ˈɛvriθɪŋ wɪl biː nuː/', '"Will" para previsões. Gerúndio como sujeito: "Leaving my friends".', '[]'::jsonb, '[{"surface":"Of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"course","pos":"noun","ipa":"/kɔːrs/","gloss":"curso (of course = claro)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"nervous","pos":"adjective","ipa":"/ˈnɜːrvəs/","gloss":"nervoso, ansioso"},{"surface":"Leaving","pos":"verb","ipa":"/ˈliːvɪŋ/","gloss":"saindo"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"easy","pos":"adjective","ipa":"/ˈiːzi/","gloss":"fácil, tranquilo"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"everything","pos":"pronoun","ipa":"/ˈɛvriθɪŋ/","gloss":"tudo"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"}]'::jsonb, NULL, NULL),
  ('unit-paragraphs-b2-10-04', 'lesson-paragraphs-b2-10', 4, 'paragraph', 'Still, I feel ready for the change. Whatever happens, I know I will learn a lot about myself.', 'Mesmo assim, me sinto pronto para a mudança. Aconteça o que acontecer, sei que vou aprender muito sobre mim mesmo.', '/stɪl aɪ fiːl ˈrɛdi fɔːr ðə tʃeɪndʒ wʌtˈɛvər ˈhæpənz aɪ noʊ aɪ wɪl lɜːrn ə lɑːt əˈbaʊt maɪˈsɛlf/', '"Still" no início = mesmo assim. "Whatever happens" = aconteça o que acontecer.', '[]'::jsonb, '[{"surface":"Still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"Whatever","pos":"pronoun","ipa":"/wʌtˈɛvər/","gloss":"o que (quer que seja)"},{"surface":"happens","pos":"verb","ipa":"/ˈhæpənz/","gloss":"acontece"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"learn","pos":"verb","ipa":"/lɜːrn/","gloss":"aprender"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"myself","pos":"pronoun","ipa":"/maɪˈsɛlf/","gloss":"eu mesmo, me"}]'::jsonb, NULL, NULL)
